import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"旅","description":"周易正義 - 旅","frontmatter":{"title":"旅","description":"周易正義 - 旅"},"headers":[],"relativePath":"classics/zhengyi/056.md","filePath":"classics/zhengyi/056.md"}'),l={name:"classics/zhengyi/056.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<blockquote><p>火山旅</p></blockquote><blockquote><p>卦辭：小亨，旅貞吉。</p></blockquote><blockquote><p>彖曰：旅小亨，柔得中乎外，而順乎剛，止而麗乎明，是以小亨旅貞吉也。旅之時義大矣哉！</p></blockquote><h1 id="旅" tabindex="-1">旅 <a class="header-anchor" href="#旅" aria-label="Permalink to “旅”">​</a></h1><p>王弼：不足全夫貞吉之道，唯足以為旅之貞吉，故特重曰“旅，貞吉”也。</p><h3 id="疏" tabindex="-1">疏 <a class="header-anchor" href="#疏" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：旅者，客寄之名，羈旅之稱，失其本居，而寄他方，謂之為旅。既為羈旅，苟求僅存，雖得自通，非甚光大，故《旅》之為義，小亨而巳，故曰“旅，小亨”。羈旅而獲小亨，是旅之正吉，故曰“旅，貞吉”也。</p><h2 id="《彖》曰-​" tabindex="-1">《彖》曰： ​ <a class="header-anchor" href="#《彖》曰-​" aria-label="Permalink to “《彖》曰： ​”">​</a></h2><h3 id="旅-小亨-柔得中乎外-而順乎剛-止而麗乎明-是以-小亨-旅貞吉-也。-​" tabindex="-1">“旅，小亨”，柔得中乎外，而順乎剛，止而麗乎明，是以“小亨，旅貞吉”也。 ​ <a class="header-anchor" href="#旅-小亨-柔得中乎外-而順乎剛-止而麗乎明-是以-小亨-旅貞吉-也。-​" aria-label="Permalink to ““旅，小亨”，柔得中乎外，而順乎剛，止而麗乎明，是以“小亨，旅貞吉”也。 ​”">​</a></h3><p>王弼：夫物失其主則散，柔乘於剛則乖。既乖且散，物皆羈旅，何由得小亨而吉乎？夫陽為物長，而陰皆順陽。唯六五乘剛，而復得中乎外，以承於上，陰兇順陽，不為乖逆。止而麗明，動不履妄，雖不及剛得尊位，恢弘大通，是以小亨。令附旅者，不失其正，得其所安也。</p><h3 id="疏-1" tabindex="-1">疏 <a class="header-anchor" href="#疏-1" aria-label="Permalink to “疏”">​</a></h3><p>“《彖》曰”至“貞吉也”。○正義曰：“旅，小亨”者，舉《經》文也。柔得中乎外而順乎剛，止而麗乎明，是以“小亨”。“旅貞吉”者，此就六五及二體，釋旅得亨貞之義，柔處於外，弱而為客之象，若所託不得其主，得主而不能順從，則乖逆而離散，何由得自通而貞吉乎？今柔雖處外而得中順陽，則是得其所託，而順從於主。又止而麗明，動不履妄，故能於寄旅之時，得通而正，不失所安也。</p><h3 id="旅之時義大矣哉-​" tabindex="-1">旅之時義大矣哉！ ​ <a class="header-anchor" href="#旅之時義大矣哉-​" aria-label="Permalink to “旅之時義大矣哉！ ​”">​</a></h3><p>王弼：旅者大散，物皆失其所居之時也。鹹失其居，物願所附，豈非知者有為之時？</p><h3 id="疏-2" tabindex="-1">疏 <a class="header-anchor" href="#疏-2" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：此嘆美寄旅之時，物皆失其所居。若能與物為附，使旅者獲安，非小才可濟，惟大智能然。故曰“旅之時義大矣哉”。</p><h2 id="《象》曰-山上有火-旅。君子以明慎用刑而不留獄。-​" tabindex="-1">《象》曰：山上有火，旅。君子以明慎用刑而不留獄。 ​ <a class="header-anchor" href="#《象》曰-山上有火-旅。君子以明慎用刑而不留獄。-​" aria-label="Permalink to “《象》曰：山上有火，旅。君子以明慎用刑而不留獄。 ​”">​</a></h2><p>王弼：止以明之，刑戮詳也。</p><h3 id="疏-3" tabindex="-1">疏 <a class="header-anchor" href="#疏-3" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：火在山上，逐草而行，勢不久留，故為旅象。又上下二體，艮止離明，故君子象此，以靜止明察，審慎用刑，而不稽留獄訟。</p><h2 id="初六-旅瑣瑣-斯其所取災。-​" tabindex="-1">初六：旅瑣瑣，斯其所取災。 ​ <a class="header-anchor" href="#初六-旅瑣瑣-斯其所取災。-​" aria-label="Permalink to “初六：旅瑣瑣，斯其所取災。 ​”">​</a></h2><p>王弼：最處下極，寄旅不得所安，而為斯賤之役，所取致災，志窮且困。</p><h3 id="疏-4" tabindex="-1">疏 <a class="header-anchor" href="#疏-4" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“旅瑣瑣，斯其所取災”者，瑣瑣者，細小卑賤之貌也。初六當旅之時，最處下極，是寄旅不得所安，而為斯卑賤之役。然則為斯卑賤勞役，由其處於窮下，故致此災，故曰“旅瑣瑣斯其所取災”也。</p><h3 id="《象》曰-旅瑣瑣-志窮災也。-​" tabindex="-1">《象》曰：“旅瑣瑣”，志窮災也。 ​ <a class="header-anchor" href="#《象》曰-旅瑣瑣-志窮災也。-​" aria-label="Permalink to “《象》曰：“旅瑣瑣”，志窮災也。 ​”">​</a></h3><h3 id="疏-5" tabindex="-1">疏 <a class="header-anchor" href="#疏-5" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“志窮災”，志意窮困，自取此災也。</p><h2 id="六二-旅即次-懷其資-得童僕貞。-​" tabindex="-1">六二：旅即次，懷其資，得童僕貞。 ​ <a class="header-anchor" href="#六二-旅即次-懷其資-得童僕貞。-​" aria-label="Permalink to “六二：旅即次，懷其資，得童僕貞。 ​”">​</a></h2><p>王弼：次者，可以安行旅之地也。懷，來也。得位居中，體柔奉上，以此寄旅，必獲次舍。懷來資貨，得童僕之所正也。旅不可以處盛，故其美盡於童僕之正也。過斯以往，則見害矣。童僕之正，義足而巳。</p><h3 id="疏-6" tabindex="-1">疏 <a class="header-anchor" href="#疏-6" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“旅即次，懷其資，得童僕貞”者，得位居中，體柔承上，以此而為寄旅，必為主君所安，旅得次舍，懷來資貨，又得童僕之正，不同初六賤役，故曰“旅即次，懷其資，得童僕貞”。</p><h3 id="《象》曰-得童僕貞-終無尤也。-​" tabindex="-1">《象》曰：“得童僕貞”，終無尤也。 ​ <a class="header-anchor" href="#《象》曰-得童僕貞-終無尤也。-​" aria-label="Permalink to “《象》曰：“得童僕貞”，終無尤也。 ​”">​</a></h3><h3 id="疏-7" tabindex="-1">疏 <a class="header-anchor" href="#疏-7" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“終無尤”者，旅不可以處盛，盛則為物所害。今惟正於童僕，則終保無咎也。</p><h2 id="九三-旅焚其次-喪其童僕-貞厲。-​" tabindex="-1">九三：旅焚其次，喪其童僕，貞厲。 ​ <a class="header-anchor" href="#九三-旅焚其次-喪其童僕-貞厲。-​" aria-label="Permalink to “九三：旅焚其次，喪其童僕，貞厲。 ​”">​</a></h2><p>王弼：居下體之上，與二相得，以寄旅之身而為施下之道，與萌侵權，主之所疑也，故次焚僕喪，而身危也。</p><h3 id="疏-8" tabindex="-1">疏 <a class="header-anchor" href="#疏-8" aria-label="Permalink to “疏”">​</a></h3><p>“九三旅焚其次”至“貞厲”。○正義曰：“旅焚其次，喪其童僕，貞厲”者，九三居下體之上，下據於二，上無其應，與二相得，是欲自尊而惠施於下也。以羈旅之身而為惠下之道，是與萌侵權，為主君之所疑也。為君主所疑，則被黜而見害，故焚其次舍，喪其童僕之正而身危也。○注“與萌”至“所疑也”。正義曰：“與萌侵權”者，言與得政事之萌，漸侵奪主君之權勢，若齊之田氏，故為主所疑也。</p><h3 id="《象》曰-旅焚其次-亦以傷矣。以旅與下-其義喪也。-​" tabindex="-1">《象》曰：“旅焚其次”，亦以傷矣。以旅與下，其義喪也。 ​ <a class="header-anchor" href="#《象》曰-旅焚其次-亦以傷矣。以旅與下-其義喪也。-​" aria-label="Permalink to “《象》曰：“旅焚其次”，亦以傷矣。以旅與下，其義喪也。 ​”">​</a></h3><h3 id="疏-9" tabindex="-1">疏 <a class="header-anchor" href="#疏-9" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“亦以傷矣”者，言失其所安，亦可悲傷也。“其義喪”者，言以旅與下，理是喪亡也。</p><h2 id="九四-旅於處-得其資斧-我心不快。-​" tabindex="-1">九四：旅於處，得其資斧，我心不快。 ​ <a class="header-anchor" href="#九四-旅於處-得其資斧-我心不快。-​" aria-label="Permalink to “九四：旅於處，得其資斧，我心不快。 ​”">​</a></h2><p>王弼：斧所以斫除荊棘，以安其舍者也。雖處上體之下，不先於物，然而不得其位，不獲平坦之地，客於所處，不得其次，而得其資斧之地，故其心不快也。</p><h3 id="疏-10" tabindex="-1">疏 <a class="header-anchor" href="#疏-10" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“旅於處，得其資斧，我心不快”者，九四處上體之下，不同九三之自尊，然不得其位，猶寄旅之人，求其次舍，不獲平坦之所，而得用斧之地。言用斧除荊棘，然後乃處，故曰“旅於處，得其資斧”也。求安處而得資斧之地，所以其心不快也。</p><h3 id="《象》曰-旅於處-未得位也。-得其資斧-心未快也。-​" tabindex="-1">《象》曰：“旅於處”，未得位也。“得其資斧”，心未快也。 ​ <a class="header-anchor" href="#《象》曰-旅於處-未得位也。-得其資斧-心未快也。-​" aria-label="Permalink to “《象》曰：“旅於處”，未得位也。“得其資斧”，心未快也。 ​”">​</a></h3><h2 id="六五-射雉一矢-亡。終以譽命。-​" tabindex="-1">六五：射雉一矢，亡。終以譽命。 ​ <a class="header-anchor" href="#六五-射雉一矢-亡。終以譽命。-​" aria-label="Permalink to “六五：射雉一矢，亡。終以譽命。 ​”">​</a></h2><p>王弼：射雉以一矢，而復亡之，明雖有雉，終不可得矣。寄旅而進，雖處於文明之中，居於貴位，此位終不可有也。以其能知禍福之萌，不安其處以乘其下，而上承於上，故終以譽而見命也。</p><h3 id="疏-11" tabindex="-1">疏 <a class="header-anchor" href="#疏-11" aria-label="Permalink to “疏”">​</a></h3><p>“六五射雉”至“以譽命”。○正義曰：“射雉一矢亡，終以譽命”者，羈旅不可以處盛位，六五以羈旅之身，進居貴位，其位終不可保，譬之射雉，惟有一矢，射之而復亡失其矢，其雉終不可得，故曰“射雉一矢亡”也。然處文明之內，能照禍福之幾，不乘下以侵權，而承上以自保，故得終以美譽而見爵命，故曰“終以譽命”也。</p><h3 id="《象》曰-終以譽命-上逮也。-​" tabindex="-1">《象》曰：“終以譽命”，上逮也。 ​ <a class="header-anchor" href="#《象》曰-終以譽命-上逮也。-​" aria-label="Permalink to “《象》曰：“終以譽命”，上逮也。 ​”">​</a></h3><h3 id="疏-12" tabindex="-1">疏 <a class="header-anchor" href="#疏-12" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“上逮”者，逮，及也，以能承及於上，故得“終以譽命”也。</p><h2 id="上九-鳥焚其巢-旅人先笑後號咷。喪牛於易-兇。-​" tabindex="-1">上九：鳥焚其巢，旅人先笑後號咷。喪牛於易，兇。 ​ <a class="header-anchor" href="#上九-鳥焚其巢-旅人先笑後號咷。喪牛於易-兇。-​" aria-label="Permalink to “上九：鳥焚其巢，旅人先笑後號咷。喪牛於易，兇。 ​”">​</a></h2><p>王弼：居高危而以為宅，巢之謂也。客旅得上位，故先笑也。以旅而處於上極，眾之所嫉也。以不親之身而當被害之地，必兇之道也，故曰“後號咷”。牛者，稼穡之資。以旅處上，無所同嫉，故“喪牛於易”，不在於難。物莫之與，危而不扶，喪牛於易，終莫之聞。莫之聞，則傷之者至矣。</p><h3 id="疏-13" tabindex="-1">疏 <a class="header-anchor" href="#疏-13" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“鳥焚其巢，旅人先笑後號咷，喪牛於易，兇”者，最居於上，如鳥之巢，以旅處上，必見傾奪，如鳥巢之被焚，故曰“鳥焚其巢”也。客得上位，所以“先笑”。兇害必至，故“後號咷”。無所同嫉，喪其稼穡之資，理在不難，故曰“喪牛於易”。物莫之與，則傷之者至矣，故曰“兇”也。</p><h3 id="《象》曰-以旅在上-其義焚也。-喪牛於易-終莫之聞也。-​" tabindex="-1">《象》曰：以旅在上，其義焚也。“喪牛於易”，終莫之聞也。 ​ <a class="header-anchor" href="#《象》曰-以旅在上-其義焚也。-喪牛於易-終莫之聞也。-​" aria-label="Permalink to “《象》曰：以旅在上，其義焚也。“喪牛於易”，終莫之聞也。 ​”">​</a></h3><h3 id="疏-14" tabindex="-1">疏 <a class="header-anchor" href="#疏-14" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“終莫之聞也”者，眾所同疾，危而不扶，至於喪牛於易，終無以一言告之，使聞而悟也。</p>',60)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
